import{EventEmitter}from'node:events';import{randomUUID}from'node:crypto';import type WebSocket from'ws';import{buildServer}from'../../apps/server/src/app.js';import{createPool}from'../../packages/db/src/index.js';
const databaseUrl=process.env.WILLIE_FAILURE_DATABASE_URL,port=Number(process.env.WILLIE_FAILURE_PORT),source=process.env.WILLIE_FAILURE_SOURCE,target=process.env.WILLIE_FAILURE_TARGET;if(!databaseUrl||!Number.isInteger(port)||!source||!target)throw Error('Explicit isolated failure-fixture configuration required');const pool=createPool(databaseUrl),sockets=new Set<Socket>();
class Socket extends EventEmitter{closed=false;deliver(type:string,payload:Record<string,unknown>){if(!this.closed)this.emit('message',Buffer.from(JSON.stringify({metadata:{message_id:randomUUID(),message_type:type,message_timestamp:new Date().toISOString()},payload})));}close(){if(!this.closed){this.closed=true;this.emit('close');}}}
const fetcher:typeof fetch=async(input,init)=>{const url=input instanceof Request?input.url:String(input);if(url.endsWith('/validate'))return Response.json({client_id:'fixture-client',user_id:(new Headers(init?.headers).get('authorization')??'').replace('OAuth fixture:',''),login:'fixture-creator',scopes:['user:read:chat'],expires_in:3600});if(url.includes('/eventsub/subscriptions'))return Response.json({data:[]},{status:202});return new Response('',{status:503});};
const app=await buildServer({pool,fetcher,restoreUserIds:[source,target],env:{NODE_ENV:'test',PORT:String(port),APP_URL:`http://127.0.0.1:${port}`,DATABASE_URL:databaseUrl,SESSION_SECRET:'willie-failure-session-secret-fixture-only',TOKEN_ENCRYPTION_KEY:'ab'.repeat(32),TWITCH_CLIENT_ID:'fixture-client',TWITCH_CLIENT_SECRET:'fixture-client-secret',TWITCH_WEBHOOK_SECRET:'willie-failure-webhook-secret-fixture-only'},socketFactory:()=>{const socket=new Socket();sockets.add(socket);queueMicrotask(()=>socket.deliver('session_welcome',{session:{id:randomUUID(),status:'connected',connected_at:new Date().toISOString(),keepalive_timeout_seconds:60,reconnect_url:null}}));return socket as unknown as WebSocket;}});
await app.ready();const keepalive=setInterval(()=>{for(const socket of sockets)socket.deliver('session_keepalive',{});},1000);await app.listen({host:'127.0.0.1',port});console.log('SIMULATED_CONTRACT_FAILURE_SERVER_READY');process.once('SIGTERM',()=>{clearInterval(keepalive);void app.close().then(()=>pool.end()).then(()=>process.exit(0),()=>process.exit(1));});
